  "grc.continuite.pra.c.validation-metier.desc": { fr: "contrôles de cohérence des données et des opérations reprises.", en: "consistency checks of resumed data and operations." },
  "grc.continuite.pra.c.retour-normal.label": { fr: "Retour à la normale", en: "Return to normal" },
  "grc.continuite.pra.c.retour-normal.desc": { fr: "critères de fin de PRA, rattrapage, communication.", en: "PRA completion criteria, catch-up, communication." },
  "grc.continuite.psi.title": { fr: "PSI — Plan de secours informatique", en: "PSI — IT Backup Plan" },
  "grc.continuite.psi.subtitle": { fr: "Le PSI organise le secours PENDANT l’incident : bascule vers les moyens de secours pour maintenir les systèmes d’information critiques.", en: "The PSI organizes backup DURING the incident: failover to backup resources to keep critical information systems running." },
  "grc.continuite.psi.hubCard.title": { fr: "PSI — Plan de secours informatique", en: "PSI — IT Backup Plan" },
  "grc.continuite.psi.hubCard.desc": { fr: "Secours pendant l’incident : bascule, site de repli, MCO.", en: "Backup during the incident: failover, recovery site, MCO." },
  "grc.continuite.psi.role": { fr: "PSI ≠ PRI : le PSI maintient le service pendant l’incident, le PRI rétablit les systèmes nominaux après.", en: "PSI ≠ PRI: the PSI keeps the service running during the incident, the PRI restores nominal systems afterwards." },
