  "grc.continuite.pri.title": { fr: "PRI — Plan de rétablissement informatique", en: "PRI — IT Restoration Plan" },
  "grc.continuite.pri.subtitle": { fr: "Le PRI organise le rétablissement APRÈS l’incident : restauration ou reconstruction des systèmes d’information et retour à l’état nominal.", en: "The PRI organizes restoration AFTER the incident: restoring or rebuilding information systems and returning to nominal state." },
  "grc.continuite.pri.hubCard.title": { fr: "PRI — Plan de rétablissement informatique", en: "PRI — IT Restoration Plan" },
  "grc.continuite.pri.hubCard.desc": { fr: "Rétablissement après l’incident : restauration, intégrité, bascule retour.", en: "Restoration after the incident: restore, integrity, failback." },
  "grc.continuite.pri.role": { fr: "Après une cyberattaque, le PRI inclut la reconstruction sur une base saine : restaurer à l’identique peut réintroduire l’attaquant.", en: "After a cyberattack, the PRI includes rebuilding on a clean base: a like-for-like restore can reintroduce the attacker." },
  "grc.continuite.pri.c.ordre.label": { fr: "Ordre de rétablissement", en: "Restoration order" },
